B.aDA=new A.ce([0,"\uace0\ub9d9\uad6c\uba3c. \uc774 \ube5a\uc740 \uc6b4\uc804\ub300\ub85c \uac1a\uc790\uace0.",3,"\u2026\uace0\ub9c8\uc6cc\uc694. \uc4f4 \uac70 \ub2e4 \ucc38\uace0 \uba39\uc5c8\uc5b4\uc694.",4,"\uc774 \ud560\ubbf8\ub97c \uba3c\uc800 \ucc59\uae30\ub2e4\uc774\u2026 \uace0\ub9d9\ub370\uc774.",5,"\uc4f0\ub2e4, \uc368. \u2026\uadf8\ub798\ub3c4 \uace0\ub9c8\uc6cc.",6,"\u2026\ube5a\uc84c\ub2e4. \uc77c\uc5b4\ub098\uba74 \uac1a\uc744\uac8c.",10,"\uace0\ub9c8\uc6cc\uc694. \ub0b4\uc77c \ubc24 \ubc29\uc1a1\uc740 \ub2f9\uc2e0\ud55c\ud14c \ubc14\uce60\uac8c\uc694.",12,"\uace0\ub9d9\ub124. \uc774 \ub299\uc740\uc774 \ud0dc\uc5fd\uc744 \ub610 \uac10\uc544 \uc8fc\ub294\uad6c\uba3c.",15,"\u2026\ube5a\uc84c\uc5b4.",17,"\u2026\uc65c \ub098\uc57c. \u2026\uace0\ub9c8\uc6cc."],t.TM)
