B.aJ9=new A.b(B.lL,["\u201c\uc7a5\uc791\uc774 \ubaa8\uc790\ub780\ub2e4. \uc624\ub298 \ubc24 \ubd88 \uc880 \ub109\ub109\ud788 \ub54c \ubcf4\uc790\uc774.\u201d","\u201c\uc1e0\ubd99\uc774 \uc880 \ubaa8\uc544 \uc624\uc774\uc18c. \ub179\uc2a8 \uac70\ub77c\ub3c4 \ub2e4 \uc4f8 \ub370\uac00 \uc788\ub370\uc774.\u201d","\u201c\ucc3d\uace0\uac00 \ube44\uc5b4 \uac04\ub2e4. \uc544\uc774\ub4e4 \ubb35\uc744 \uac70\ub77c\ub3c4 \ucc44\uc6cc \ub193\uc790.\u201d","\u201c\uc9c0\ubd95\uc5d0 \uad6c\uba4d\uc774 \ub0ac\ub370\uc774. \ucca0\ud310\uc73c\ub85c \ub36e\uc5b4\uc57c \uc548 \ub418\uaca0\ub098.\u201d","\u201c\ube68\ub7ab\uc904\uc774 \ub04a\uc5b4\uc84c\ub370\uc774. \ubc27\uc904 \uc880 \uaf2c\uc544 \uc8fc\uaca0\ub098?\u201d","\u201c\uc800 \ub108\uba38\uc5d0 \ubb50\uac00 \uc788\ub294\uace0 \uad81\uae08\ud558\ub370\uc774. \ucabc\ub9e4\ub9cc \ub354 \ubc1d\ud600 \ub3c4.\u201d","\u201c\uba40\ub9ac\uc11c \uc5f0\uae30\uac00 \uc62c\ub77c\uc628\ub2e4. \ub204\uac00 \ucacc \uac00 \ubd10\uc57c \uc548 \ub418\uaca0\ub098.\u201d","\u201c\uc9c0\ud558\ucca0\uc5ed \ub9e4\uc810\uc5d0 \ud1b5\uc870\ub9bc\uc774 \ub0a8\uc544 \uc788\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub370\uc774. \ud55c\ubc88 \ub0b4\ub824\uac00 \ubcf4\uc774\uc18c.\u201d","\u201c\ub77c\ub514\uc624\uc5d0\uc11c \ub204\uac00 \ubd80\ub974\ub294 \uac70 \uac19\ub354\ub77c. \ub2e4\uc774\uc5bc \uc880 \ub3cc\ub824 \ubcf4\uc774\uc18c.\u201d","\u201c\ub2e4\ub4e4 \ub9d0\uc740 \uc548 \ud574\ub3c4 \ubd80\ud0c1\uc774 \ud558\ub098\uc529 \uc788\uc744 \ub07c\ub2e4.\u201d","\u201c\uc624\ub298 \ubc24\ub3c4 \ubb34\uc0ac\ud788 \ub118\uae30\uc7ac\uc774. \uadf8\ub77c\ubbc4 \ub530\uc21c \uad6d \ud55c \uadf8\ub987 \ud558\uc790.\u201d","\u201c\uc694\uc0c8 \ub2e4\ub4e4 \uc9c0\ucce4\ub370\uc774. \uc794\uce58 \ud55c\ubc88 \uc5f4\uc790.\u201d"],t.w)
B.aJ6=new A.b(B.lL,["\u201c\uc7a5\uc791\uc774 \ubaa8\uc790\ub77c\ub124. \uc624\ub298 \ubc24 \ubd88 \uc880 \ub109\ub109\ud788 \ud53c\uc6b0\uc138.\u201d","\u201c\uace0\ucca0\ub9cc \uc788\uc73c\uba74 \uc774\uac83\uc800\uac83 \uace0\uccd0 \ubcf4\uaca0\ub124.\u201d","\u201c\ucc3d\uace0\uac00 \ube44\uc5b4 \uac00\ub294\uad6c\uba3c. \uc544\uc774\ub4e4 \uba39\uc744 \uac70\ub77c\ub3c4 \ucc44\uc6cc \ub450\uac8c.\u201d","\u201c\uc9c0\ubd95\uc5d0 \uad6c\uba4d\uc774 \ub0ac\ub124. \ucca0\ud310\uc73c\ub85c \ub36e\uc5b4\uc57c\uaca0\uc5b4.\u201d","\u201c\ube68\ub7ab\uc904\uc774 \ub04a\uc5b4\uc84c\ub124. \ubc27\uc904 \uc880 \uaf2c\uc544 \uc8fc\uaca0\ub098?\u201d","\u201c\uc800 \ub108\uba38\uc5d0 \ubb50\uac00 \uc788\ub294\uc9c0 \uad81\uae08\ud558\uad6c\uba3c. \uc870\uae08\ub9cc \ub354 \ubc1d\ud600 \uc8fc\uac8c.\u201d","\u201c\uc9c0\ub3c4\uc5d0 \ud45c\uc2dc\ud574 \ub454 \uacf3\uc774 \uc788\ub124. \ub204\uac00 \ub2e4\ub140\uc640 \uc8fc\uaca0\ub098?\u201d","\u201c\uc9c0\ud558\uc5d0\uc11c \uc774\uc0c1\ud55c \uc18c\ub9ac\uac00 \ub0ac\ub2e4\ub354\uad70. \ud55c\ubc88 \ub0b4\ub824\uac00 \ubcf4\uac8c.\u201d","\u201c\ub77c\ub514\uc624\uc5d0\uc11c \ub204\uac00 \ubd80\ub974\ub294 \uac83 \uac19\uc558\ub124. \ub2e4\uc774\uc5bc \uc880 \ub3cc\ub824 \ubcf4\uac8c.\u201d","\u201c\ub2e4\ub4e4 \ub9d0\uc740 \uc548 \ud574\ub3c4 \ubd80\ud0c1\uc774 \ud558\ub098\uc529 \uc788\uc744 \uac78\uc138.\u201d","\u201c\uc624\ub298 \ubc24\ub3c4 \ubb34\uc0ac\ud788 \ub118\uae30\uc138. \uadf8\ub7fc \ucc28 \ud55c\uc794\ud558\uc138.\u201d","\u201c\uc694\uc998 \ub2e4\ub4e4 \uc9c0\ucce4\uad6c\uba3c. \uc794\uce58 \ud55c\ubc88 \uc5ec\uc138.\u201d"],t.w)
